/** MIT; product-local closed contours. */
import * as THREE from'three';import{mesh}from'../../modeling/parts.js';import{roundedRect}from'../../core/geometry.js';
export function hole(s,x,y,r){const p=new THREE.Path();p.absarc(x,y,r,0,Math.PI*2,false);s.holes.push(p);}
export function solid(parent,s,d,p,m,n){return mesh(parent,new THREE.ExtrudeGeometry(s,{depth:d,bevelEnabled:false,curveSegments:32}),m,p,n);}
/** Axis endpoints in Three's LatheGeometry create redundant zero-area triangles. */
export function lathe(profile,segments=96){const g=new THREE.LatheGeometry(profile.map(p=>new THREE.Vector2(...p)),segments),p=g.attributes.position,index=g.index,kept=[],a=new THREE.Vector3(),b=new THREE.Vector3(),c=new THREE.Vector3();for(let i=0;i<index.count;i+=3){const ids=[index.getX(i),index.getX(i+1),index.getX(i+2)];a.fromBufferAttribute(p,ids[0]);b.fromBufferAttribute(p,ids[1]);c.fromBufferAttribute(p,ids[2]);if(b.sub(a).cross(c.sub(a)).lengthSq()>1e-16)kept.push(...ids);}g.setIndex(kept);return g.rotateX(Math.PI/2);}
export function ringShape(w,h,r,iw,ih,ir){const s=roundedRect(w,h,r);s.holes.push(roundedRect(iw,ih,ir,{path:new THREE.Path(),clockwise:true}));return s;}
export function frontShape(){const s=new THREE.Shape();s.moveTo(-8,-24);s.lineTo(-5.15,-24);s.lineTo(-5.15,-17.1);s.lineTo(5.15,-17.1);s.lineTo(5.15,-24);s.lineTo(8,-24);s.absarc(8,-20,4,-Math.PI/2,0,false);s.lineTo(12,20);s.absarc(8,20,4,0,Math.PI/2,false);s.lineTo(-8,24);s.absarc(-8,20,4,Math.PI/2,Math.PI,false);s.lineTo(-12,-20);s.absarc(-8,-20,4,Math.PI,Math.PI*1.5,false);s.closePath();s.holes.push(roundedRect(19,19,.45,{cy:8,path:new THREE.Path(),clockwise:true}));return s;}
export function openRing(){const s=new THREE.Shape();s.moveTo(-5.15,-24);s.lineTo(-8,-24);s.absarc(-8,-20,4,-Math.PI/2,-Math.PI,true);s.lineTo(-12,20);s.absarc(-8,20,4,Math.PI,Math.PI/2,true);s.lineTo(8,24);s.absarc(8,20,4,Math.PI/2,0,true);s.lineTo(12,-20);s.absarc(8,-20,4,0,-Math.PI/2,true);s.lineTo(5.15,-24);s.lineTo(5.15,-22.8);s.lineTo(8,-22.8);s.absarc(8,-20,2.8,-Math.PI/2,0,false);s.lineTo(10.8,20);s.absarc(8,20,2.8,0,Math.PI/2,false);s.lineTo(-8,22.8);s.absarc(-8,20,2.8,Math.PI/2,Math.PI,false);s.lineTo(-10.8,-20);s.absarc(-8,-20,2.8,Math.PI,Math.PI*1.5,false);s.lineTo(-5.15,-22.8);s.closePath();return s;}
export function boardShape(){const s=new THREE.Shape();s.moveTo(-10.3,-19.8);s.lineTo(-8.3,-21.8);s.lineTo(-5.15,-21.8);s.lineTo(-5.15,-17);s.lineTo(5.15,-17);s.lineTo(5.15,-21.8);s.lineTo(8.3,-21.8);s.lineTo(10.3,-19.8);s.lineTo(10.3,-15.55);s.lineTo(8,-15.55);s.absarc(8,-12,3.55,-Math.PI/2,-Math.PI*1.5,true);s.lineTo(10.3,-8.45);s.lineTo(10.3,19.8);s.lineTo(8.3,21.8);s.lineTo(-8.3,21.8);s.lineTo(-10.3,19.8);s.lineTo(-10.3,-8.45);s.lineTo(-8,-8.45);s.absarc(-8,-12,3.55,Math.PI/2,-Math.PI/2,true);s.lineTo(-10.3,-15.55);s.closePath();return s;}
